mapper.select:
SELECT t1.ROUTER_ID  FROM sg_tccon_tcrouter_r_fiber t1
WHERE t1.FIBER_ID = #{resId}
UNION
select t1.OPTICAL_ID from `tms`.sg_tccon_tcrouter_r_tcopticalroad t1
join (SELECT IS_HGS from `tms`.sg_tcdev_fiber_b where id = #{resId} ) t2 on  t2.IS_HGS = '0'
where t1.RES_ID in (
    select ID from `tms`.SG_TCDEV_FIBERLINE_B where PAR_FIBER_SEG in (select FIBERSEG_ID from `tms`.SG_TCDEV_FIBERSEG_R_FIBER where FIBER_ID = #{resId})
) OR Z_RES_ID in (
    select ID from `tms`.SG_TCDEV_FIBERLINE_B where PAR_FIBER_SEG in (select FIBERSEG_ID from `tms`.SG_TCDEV_FIBERSEG_R_FIBER where FIBER_ID = #{resId})
)
UNION
select t1.OPTICAL_ID from `tms`.sg_tccon_tcrouter_r_tcopticalroad t1
join (SELECT IS_HGS from `tms`.sg_tcdev_fiber_b where id = #{resId} ) t2 on  t2.IS_HGS = '1'
where t1.RES_ID in (
    select FIBERSEGLINE_ID from sg_tccon_fiberline_r_fibersegline where PAR_FIBER = #{resId}
) OR Z_RES_ID in (
    select FIBERSEGLINE_ID from sg_tccon_fiberline_r_fibersegline where PAR_FIBER = #{resId}
)
UNION
select t1.ID FROM SG_TCCON_TCOPTICALROAD_B t1 where  t1.LOAD_BEARING_OTN_CHANNEL_ID in (
    SELECT t2.CHANNEL_ID FROM sg_tccon_tcrouter_r_fiber t1
    join `tms`.nr_res_channelroutenode_m t2 on t2.RES_ID = t1.ROUTER_ID
    WHERE t1.FIBER_ID = #{resId}
    UNION
    select t2.CHANNEL_ID from `tms`.sg_tccon_tcrouter_r_tcopticalroad t1
    join (SELECT IS_HGS from `tms`.sg_tcdev_fiber_b where id = #{resId} ) t3 on  t3.IS_HGS = '0'
    join `tms`.nr_res_channelroutenode_m t2 on t2.RES_ID = t1.OPTICAL_ID
    where t1.RES_ID in (
        select ID from `tms`.SG_TCDEV_FIBERLINE_B where PAR_FIBER_SEG in (select FIBERSEG_ID from `tms`.SG_TCDEV_FIBERSEG_R_FIBER where FIBER_ID = #{resId})
    ) OR Z_RES_ID in (
        select ID from `tms`.SG_TCDEV_FIBERLINE_B where PAR_FIBER_SEG in (select FIBERSEG_ID from `tms`.SG_TCDEV_FIBERSEG_R_FIBER where FIBER_ID = #{resId})
    )
    UNION
    select t2.CHANNEL_ID from `tms`.sg_tccon_tcrouter_r_tcopticalroad t1
    join (SELECT IS_HGS from `tms`.sg_tcdev_fiber_b where id = #{resId} ) t3 on  t3.IS_HGS = '1'
    join `tms`.nr_res_channelroutenode_m t2 on t2.RES_ID = t1.OPTICAL_ID
    where t1.RES_ID in (
        select FIBERSEGLINE_ID from sg_tccon_fiberline_r_fibersegline where PAR_FIBER = #{resId}
    ) OR Z_RES_ID in (
        select FIBERSEGLINE_ID from sg_tccon_fiberline_r_fibersegline where PAR_FIBER = #{resId}
    )
)

SELECT t2.RES_ID FROM `tms`.sg_tccon_tcbuz_r_tcchannel t1
join `tms`.nr_res_channelroutenode_m t2 on t2.CHANNEL_ID = t1.CHANNEL_ID
WHERE t1.BUZ_ID = #{resId}

SELECT DISTINCT t2.BUZ_ID FROM `tms`.nr_res_channelroutenode_m t1
JOIN `tms`.sg_tccon_tcbuz_r_tcchannel t2 ON t2.CHANNEL_ID = t1.CHANNEL_ID
WHERE t1.RES_ID = #{resId}

SELECT DISTINCT tt.ID FROM `tms`.SG_TCDEV_TCPORT_B t
JOIN `tms`.SG_TCCON_TCOPTICALROAD_B tt ON ( tt.A_PORT = t.ID OR tt.Z_PORT = t.ID )
WHERE t.PAR_CARD = #{resId}

SELECT DISTINCT tt.PAR_STATION from `tms`.SG_TCCON_TCRACK_B t
JOIN `tms`.SG_TCCON_TCROOM_B tt on tt.ID = t.PAR_ROOM
where t.ID = #{resId}

select b.id from `tms`.SG_TCCON_TCROOM_B a
join `tms`.sg_tcdev_tcnesdh_b b on b.PAR_ROOM = a.id
where a.PAR_STATION = #{resId}

select b.id from `tms`.SG_TCCON_TCROOM_B a
join `tms`.sg_tcdev_tcneotn_b b on b.PAR_ROOM = a.id
where a.PAR_STATION = #{resId}
